from contextlib import contextmanager
import os
import re
from taf.collectors.core.entities import managed_ssh_connection


class AirphoneInformationProvider:
    def __init__(self, tl_config_information_provider):
        """
        Constructor.

        :param TestlineConfigurationInformationProvider tl_config_information_provider:
            Testline configuration information provider.
        """
        self._tl_config_information_provider = tl_config_information_provider

    @contextmanager
    def lmp_connection(self, node_id=0):
        """Accessor for the lmp connection to fetch different information from the airphone.
        """
        lmp_connection = self._tl_config_information_provider.get_ue_lmp_connection(node_id=node_id)
        ssh_connection = managed_ssh_connection.ManagedSshConnection(
            host=lmp_connection.addr,
            user=lmp_connection.username,
            password=lmp_connection.password)

        ssh_connection.setup()
        try:
            yield ssh_connection
        finally:
            ssh_connection.teardown()

    def get_airphone_unit_type(self, node_id=0, capu_id=None):
        if capu_id is not None:
            command = f'echo "timeout 0.1 sysinfo | grep ID_00_MODULE_ID_" | bsh {capu_id + 1}:0'
        else:
            command = 'timeout 1 sysinfo | grep ID_00_MODULE_ID_'

        with self.lmp_connection() as ssh_connection:
            sys_info = ssh_connection.execute(command=command, timeout=60)

        pattern = re.compile(r'ID_00_MODULE_ID_\[(\d)\]=.(A[BS][IO][BEKLMNOP])')
        matches = pattern.search(sys_info)

        try:
            if matches:
                modules_detected = matches.groups()[1]
                return modules_detected
        except AttributeError:
            pass

    def get_airphone_capacity_unit_type(self, node_id=0, capu_id=0):
        return self.get_airphone_unit_type(node_id=node_id, capu_id=node_id)

    def get_airphone_common_unit_type(self, node_id=0):
        return self.get_airphone_unit_type(node_id=node_id)

    def get_airphone_mirroring_interface(self, node_id=0):
        """As proposed by airphone team, we shortly start the mirroring to determine the
        mirroring interface, so we are able to set up our collector correspondingly.
        """

        scripts = ['/opt/wts/latest/sosReport_ASIL/airphone_mirror.sh',
                   '/opt/wts/latest/sosReport_ASIL/gnbMirroring.py']

        with self.lmp_connection(node_id=node_id) as ssh_connection:
            sftp = ssh_connection.files
            ssh_connection.execute('mkdir -p /ffs/run/config/scripts/')
            for script in scripts:
                sftp.put(script, '/ffs/run/config/scripts/' + os.path.basename(script))

            ssh_connection.execute('chmod +x /ffs/run/config/scripts/airphone_mirror.sh')
            ssh_connection.execute('cd /ffs/run/config/scripts && ./airphone_mirror.sh')
            ps_output = ssh_connection.execute('ps -aux | grep [C]CSPacketCapture')
            ssh_connection.execute('cd /ffs/run/config/scripts && ./airphone_mirror.sh --stop')
            ni_match = re.search("-i (.*) -w", ps_output)
            if ni_match:
                return ni_match.group(1)
